void Solver::bump_var(int var, double coeff) {
    // Validate variable index
    if (var <= 0 || var > vars) return;

    // Increase activity with the given coefficient
    double delta = var_inc * coeff;
    activity[var] += delta;

    // Rescale all activities if the current one exceeds a safe limit
    const double ACT_LIMIT = 1e120;
    if (activity[var] > ACT_LIMIT) {
        const double SCALE = 1e-120;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= SCALE;
        }
        var_inc *= SCALE;
    }

    // Update the VSIDS priority queue
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        vsids.insert(var);
    }
}
